    self.vocab_file = vocab_file
    self.sp_model = spm.SentencePieceProcessor()
    self.sp_model.load(vocab_file)

    self.unk_token = unk_token
    self.bos_token = bos_token
    self.eos_token = eos_token功能： 加载 SentencePiece 模型文件，建立分词器实例。定义特殊标记：&lt;unk&gt; 表示未知词，&lt;s&gt; 表示序列开始，&lt;/s&gt; 表示序列结束。使用方法： 实例化时需要提供 SentencePiece 模型文件路径。 tokenizer = SimpleLlamaTokenizer(&#34;tokenizer.model&#34;) 2. 分词（tokenize）def tokenize(self, text: str) -&gt; List[str]:
    return self.sp_model.encode_as_pieces(text)功能： 将输入字符串分解为子词单元（token）。使用场景： 处理自然语言文本，将其转换为模型可处理的子词形式。例子： tokens = tokenizer.tokenize(&#34;Hello world!&#34;) print(tokens)  # [&#39;▁Hello&#39;, &#39;▁world&#39;, &#39;!&#39;] 3. 转换 Token 为 IDdef convert_tokens_to_ids(self, tokens: List[str]) -&gt; List[int]:
    return [self.sp_model.piece_to_id(token) for token in tokens]功能： 将子词 token 映射为其在词表中的索引 ID。使用场景： 模型输入需要整数表示而非字符串。例子： token_ids = tokenizer.convert_tokens_to_ids([&#39;▁Hello&#39;, &#39;▁world&#39;, &#39;!&#39;]) print(token_ids)  # [15043, 29871, 29] 4. 转换 ID 为 Tokendef convert_ids_to_tokens(self, ids: List[int]) -&gt; List[str]:
    return [self.sp_model.id_to_piece(id_) for id_ in ids]功能： 将整数 ID 映射回子词 token。使用场景： 用于将模型输出的 token ID 还原为人类可读的字符串。例子： tokens = tokenizer.convert_ids_to_tokens([15043, 29871, 29]) print(tokens)  # [&#39;▁Hello&#39;, &#39;▁world&#39;, &#39;!&#39;] 5. 解码 Token IDdef decode(self, token_ids: List[int]) -&gt; str:
    return self.sp_model.decode_ids(token_ids)功能： 将一组 token ID 转换为完整的字符串。使用场景： 模型生成输出后需要转换为人类可读的文本。例子： text = tokenizer.decode([15043, 29871, 29]) print(text)  # &#34;Hello world!&#34; 6. 添加特殊 Tokendef add_special_tokens(self, token_ids: List[int]) -&gt; List[int]:
    bos_id = self.sp_model.piece_to_id(self.bos_token)
    eos_id = self.sp_model.piece_to_id(self.eos_token)
    return [bos_id] + token_ids + [eos_id]功能： 在序列开头添加 &lt;s&gt;，在末尾添加 &lt;/s&gt;。使用场景： 为语言模型输入增加上下文信息。例子： token_ids = tokenizer.convert_tokens_to_ids([&#39;▁Hello&#39;, &#39;▁world&#39;, &#39;!&#39;]) special_ids = tokenizer.add_special_tokens(token_ids) print(special_ids)  # [1, 15043, 29871, 29, 2] 7. 保存词表def save_vocab(self, save_directory: str) -&gt; str:
    if not os.path.exists(save_directory):
        os.makedirs(save_directory)
    save_path = os.path.join(save_directory, os.path.basename(self.vocab_file))
    self.sp_model.save(save_path)
    return save_path功能： 将当前的分词器模型保存到指定目录。使用场景： 需要备份或在其他环境中重新加载分词器。例子： save_path = tokenizer.save_vocab(&#34;./vocab_backup&#34;) print(save_path)  # ./vocab_backup/tokenizer.model 使用场景总结文本预处理：将自然语言文本转为 token ID，用于深度学习模型输入。模型推理后处理：将模型生成的 token ID 解码为人类可读文本。特殊标记处理：为序列添加开头和结尾标记，确保模型理解序列结构。二、简易版的AutoTokenizerclass AutoTokenizer:
    &#34;&#34;&#34;
    A generic tokenizer class for dynamically instantiating specific tokenizer classes based on the model.
    Must be instantiated via `AutoTokenizer.from_pretrained()`.
    &#34;&#34;&#34;

    def __init__(self):
        raise EnvironmentError(
            &#34;AutoTokenizer must be instantiated using the `AutoTokenizer.from_pretrained(pretrained_model_name_or_path)` method.&#34;
        )

    @classmethod
    def from_pretrained(cls, pretrained_model_name_or_path, *inputs, **kwargs):
        &#34;&#34;&#34;
        Instantiate a tokenizer from a pretrained model or vocabulary files.

        Args:
            pretrained_model_name_or_path (str): Model ID, directory, or path to a tokenizer vocabulary.
            use_fast (bool): Whether to use a fast tokenizer if available. Defaults to True.
            trust_remote_code (bool): Whether to allow custom models from the Hugging Face Hub. Defaults to False.
            kwargs: Additional parameters passed to the tokenizer&#39;s `from_pretrained` method.

        Returns:
            PreTrainedTokenizer: The instantiated tokenizer.
        &#34;&#34;&#34;
        use_fast = kwargs.pop(&#34;use_fast&#34;, True)
        trust_remote_code = kwargs.pop(&#34;trust_remote_code&#34;, False)

        # Load tokenizer config
        tokenizer_config = get_tokenizer_config(pretrained_model_name_or_path, **kwargs)
        config_tokenizer_class = tokenizer_config.get(&#34;tokenizer_class&#34;)

        # Try to load the tokenizer class
        if config_tokenizer_class is not None:
            tokenizer_class = None
            if use_fast and not config_tokenizer_class.endswith(&#34;Fast&#34;):
                tokenizer_class = tokenizer_class_from_name(config_tokenizer_class + &#34;Fast&#34;)
            if tokenizer_class is None:
                tokenizer_class = tokenizer_class_from_name(config_tokenizer_class)
            if tokenizer_class is None:
                raise ValueError(f&#34;Tokenizer class {config_tokenizer_class} could not be found.&#34;)
            return tokenizer_class.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)

        # Fallback to mapping
        config = AutoConfig.from_pretrained(pretrained_model_name_or_path, **kwargs)
        model_type = config_class_to_model_type(type(config).__name__)
        if model_type is not None:
            tokenizer_class_py, tokenizer_class_fast = TOKENIZER_MAPPING.get(type(config), (None, None))
            if use_fast and tokenizer_class_fast:
                return tokenizer_class_fast.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)
            elif tokenizer_class_py:
                return tokenizer_class_py.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)

        raise ValueError(
            f&#34;Unrecognized configuration class {type(config).__name__}. Ensure the tokenizer mapping is updated.&#34;
        )

