	ray.Direction = m_ActiveCamera-&gt;GetRayDirections()[x + y * m_FinalImage-&gt;GetWidth()];

	// final color
	glm::vec3 color(0.0f);
	float multiplier = 1.0f;

	// path tracing
	int bounces = 5; 
	for (int i = 0; i &lt; bounces; i++) // -&gt; games101里是RR算法
	{
		// Trace Ray 判断是否击中物体 r, wi ，

		Renderer::HitPayload payload = TraceRay(ray);// 也就是interact()
                // payloac记录各种信息，是否击中，角度，物体索引等等
		if (payload.HitDistance &lt; 0.0f)  // miss时返回-1
		{
			glm::vec3 skyColor = glm::vec3(0.6f, 0.7f, 0.9f);
			color += skyColor * multiplier;
			break;
		}

		// 击中物体
		// Lo += L_i * f_r * cosine / pdf(wi)
		glm::vec3 lightDir = glm::normalize(glm::vec3(-1, -1, -1));  // 只考虑light
		float lightIntensity = glm::max(glm::dot(payload.WorldNormal, -lightDir), 0.0f); // == cos(angle) Li或者shade  li * dot(n, wi)

		const Sphere&amp; sphere = m_ActiveScene-&gt;Spheres[payload.ObjectIndex];  // obj
		const Material&amp; material = m_ActiveScene-&gt;Materials[sphere.MaterialIndex]; // 对应的材质  

		glm::vec3 sphereColor = material.Albedo;  // f_r(BRDF)  fr(p, wi, wo)
		sphereColor *= lightIntensity;
		color += sphereColor * multiplier;  // Lo += L_i * f_r * cosine

		multiplier *= 0.5f;

		// 当hit到物体时，需要改变光线的起点和方向
		// Tips: 这里是一个粗造度的hack ， 可以用BRDF项来表示对光线反射的影响
                、s
                // next_ray = spawnRay(payload, Ray)
		ray.Origin = payload.WorldPosition + payload.WorldNormal * 0.0001f;

		ray.Direction = glm::reflect(ray.Direction,
			payload.WorldNormal + material.Roughness * Walnut::Random::Vec3(-0.5f, 0.5f));
	}

	return glm::vec4(color, 1.0f);
}

Renderer::HitPayload Renderer::TraceRay(const Ray&amp; ray)
{
	// 计算与2d的圆是否相交的公式：(bx^2 + by^2) * t^2 + (2axbx + 2ayby) * t + (ax^2 + ay^2 - r^2) = 0 
	// 圆心在000
	// a是ray的原点
	// b是ray的方向
	// r是圆的半径
	// t是hit distance射线的长度
	int closestSphere = -1;  // 最近的球的序号index
	float hitDistance = std::numeric_limits&lt;float&gt;::max();  // 最近的球的距离 FLT_MAX相对来说占用更小
	// 这里是球体计算，三角形是MT算法
	for (size_t i = 0; i &lt; m_ActiveScene-&gt;Spheres.size(); i++)  // 光追的内层循环是对每个物体（将像素投影到物体上）计算是否和物体相交（光栅化这步是在外循环中）
	{
		const Sphere&amp; sphere = m_ActiveScene-&gt;Spheres[i];
		// (x - a)  (y - a)
		glm::vec3 origin = ray.Origin - sphere.Position;

		// float a = rayDirection.x * rayDirection.x + rayDirection.y * rayDirection.y + rayDirection.z * rayDirection.z;
		float a = glm::dot(ray.Direction, ray.Direction);  // firstTerm
		float b = 2.0f * glm::dot(origin, ray.Direction);  // SecondTerm
		float c = glm::dot(origin, origin) - sphere.Radius * sphere.Radius;  // ThirdTerm

		// Quadratic forumula discriminant:
		// b^2 - 4ac

		float discriminant = b * b - 4.0f * a * c;
		if (discriminant &lt; 0.0f)
			continue;

		// Quadratic formula:
		// (-b +- sqrt(discriminant)) / 2a

		// float t0 = (-b + glm::sqrt(discriminant)) / (2.0f * a); // Second hit distance (currently unused)
		float closestT = (-b - glm::sqrt(discriminant)) / (2.0f * a);

		// 更新序号和距离
		if (closestT &gt; 0.0f &amp;&amp; closestT &lt; hitDistance)
		{
			hitDistance = closestT;
			closestSphere = (int)i;
		}
	}

	if (closestSphere &lt; 0)
		return Miss(ray);  // 未击中物体，hitdistance返回-1

	return ClosestHit(ray, hitDistance, closestSphere);  // 返回击中物体的信息

}
