{
    vec3 totalIrradiance = vec3(0.0);

    int numSamples = 512; // 采样数量

    for (int i = 0; i &lt; numSamples; ++i)
    {
        // 在半球内随机采样一个方向
        vec3 sampleDir = RandomDirectionInHemisphere(normal);

        // 计算采样方向的环境光照贡献，例如从环境贴图中采样
        vec3 irradiance = SampleEnvironmentMap(sampleDir);

        // 计算采样点在法线方向上的投影
        float dotProduct = max(dot(sampleDir, normal), 0.0);

        // 累加环境光照贡献
        totalIrradiance += dotProduct * irradiance;
    }

    // 对累加的环境光照进行平均
    return totalIrradiance / float(numSamples);
}2. 球谐函数vec3 ApproximateSHLight(vec3 normal)
{
    vec3 irradiance = vec3(0.0);

    // 遍历球谐函数系数
    for (int l = 0; l &lt; SH_ORDER; ++l)
    {
        for (int m = -l; m &lt;= l; ++m)
        {
            // 计算球谐函数的值
            float shValue = EvaluateSH(l, m, normal);

            // 使用系数和球谐函数的值计算环境光照贡献
            irradiance += shCoefficients[l * SH_ORDER + m] * shValue;
        }
    }

    return irradiance;
