#load *.so that may need
if [ -r /sbin/ldconfig ]; then
ldconfig
fi

#add the libs PATH that may need
export LD_LIBRARY_PATH=&#34;/lib&#34;

#count is the counter of test started times
count=0

#main loop
while [ 1 ] ;do
#add execute property for /mnt/test/test
chmod +x /mnt/test/test
#start test
/mnt/test/test
#the running times counter
let count=count+1
echo &#34;test running times is $count&#34;
#Is test running too many times?
if [ &#34;$count&#34; -gt 100 ]; then
echo &#34;Will reboot because of test running too many times&#34;
reboot
fi
#wait for test stoping...
sleep 3
done3.2 ubootbootloader1、Linux启动需要一个bootloader程序，初始化时钟、中断或者其他外设，然后将Linux内核从flash拷贝到SDRAM中，最后启动Linux内核。2、Bootloader就是一小段程序，它在系统上电时开始执行，初始化硬件设各、准备好软件环境，最后调用操作系统内核。uboot启动流程u-boot系统启动流程 ,大多数bootloader都分为stage1和stage2两部分, u-boot也不例外。依赖于CPU体系结构的代码（如设备初始化代码等）通常都放在stage1且可以用汇编语言来实现，而stage2则通常用C语言来实现，这样可以实现复杂的功能，而且有更好的可读性和移植性。1、Stage1 start.S代码结构 u-boot的stage1代码通常放在start.S文件中，他用汇编语言写成，其主要代码部分如下（1） 定义入口:该工作通过修改连接器脚本来完成。（2）设置异常向量（Exception Vector）。（3）设置CPU的速度、时钟频率及终端控制寄存器。（4）初始化内存控制器。（5）将ROM中的程序复制到RAM中。（6）初始化堆栈。（7）转到RAM中执行，该工作可使用指令ldr pc来完成2、Stage2C语言代码部分 lib_arm/board.c中的start arm boot是C语言开始的函数也是整个启动代码中C语言的主函数，同时还是整个u-boot（armboot）的主函数，该函数只要完成如下操作：（1）调用一系列的初始化函数。（2）初始化Flash设备。（3）初始化系统内存分配函数。（4）如果目标系统拥有NAND设备，则初始化NAND设备。（5）如果目标系统有显示设备，则初始化该类设备。（6）初始化相关网络设备，填写IP、MAC地址等。（7）进去命令循环（即整个boot的工作循环），接受用户从串口输入的命令，然后进行相应的工作uboot启动过程中做了那些事？1、初始化时钟，关闭看门狗，关中断，启动ICACHE，关闭DCACHE和TLB，关闭MMU，初始化SDRAM，初始化NAND FLASH，重定位。2、初始化一个串口，检测系统内存映射，将内核映象和根文件系统映象从 Flash上读到SDRAM空间中，为内核设置启动参数，调用内核。uboot和内核如何完成参数传递？1、完成相关设置：CPU寄存器设置 R0=0 R1=机器类型ID R2=启动参数标记列表在RAM中起始基地址，设置禁止中断，SVC模式（超级用户模式，有利于硬件初始化）MMU关闭2、uboot把机器ID通过R1传递给内核，R2存放块内存的基地址，这块内存主要存放uboot给Linux内核的其他参数，参数很多所有需要按规定存放，标记是一种数据结构。3、标记的数据结构为tag，它由一个tag_header结构和一个联合（union）组成为什么uboot要关掉caches？caches是cpu内部的一个2级缓存，它的作用是将常用的数据和指令放在cpu内部。caches是通过CP15管理的，刚上电的时候，cpu还不能管理caches。上电的时候指令cache可关闭，也可不关闭，但数据cache一定要关闭，否则可能导致刚开始的代码里面，去取数据的时候，从cache里面取，而这时候RAM中数据还没有caches过来，导致数据预取异常 。3.3 文件系统什么是根文件系统？1、内核启动时所挂载（mount）的第一个文件系统，内核代码的映像文件保存在根文件系统中。2、挂载之后会把一些初始化脚本和服务加载到内存中去运行。根文件系统为啥这么重要？1、根文件系统包含系统启动时所必须的目录和关键性的文件，以及使其他文件系统得以挂载（mount）所必要的文件。比如shell命令程序必须运行在根文件系统上，譬如ls、cd等命令。2、一套linux体系，只有内核本身是不能工作的，必须要rootfs（上的etc目录下的配置文件、/bin/sbin等目录下的shell命令，还有/lib目录下的库文件等）相配合才能工作。3.4 中断硬中断 / 软中断是什么？有什么区别？1、硬中断是由硬件产生的，软中断是执行中断指令产生的。2、硬中断可以直接中断CPU，软中断并不会直接中断CPU。也只有当前正在运行的代码（或进程）才会产生软中断。3、硬中断可屏蔽、软中断不可屏蔽4、硬中断又称上半部，要快速完成任务中断为什么要区分上半部和下半部？1、调用过程：外部中断产生-&gt;发送中断信号到中断控制器-&gt;通知处理器产生中断的中断号2、为了能被新的中断打断。将中断处理一分为二，上半部登记新的中断，处理快速简单的任务，复杂耗时的任务给下半段处理，所以下半段可以被打断。3、中断下半部一般使用tasklet或工作队列实现linux中断的响应执行流程？cpu接受中断-&gt;保存中断上下文跳转到中断处理历程-&gt;执行中断上半部-&gt;执行中断下半部-&gt;恢复中断上下文。3.5 Linux驱动模型字符设备驱动模型请简述主设备号和次设备号的用途主设备号：主设备号标识设备对应的特定的驱动程序。虽然现代的linux内核允许多个驱动程序共享主设备号，但我们看待的大多数设备仍然按照“一个主设备对应一个驱动程序”的原则组织。**次设备号：**次设备号由内核使用，用于确定由主设备号对应驱动程序中的各个设备。依赖于驱动程序的编写方式，我们可以通过次设备号获得一个指向内核设备的直接指针，也可将此设备号当作设备本地数组的索引。（多个设备共用一套程序的话，主设备号代表这个驱动程序，每个设备一个次设备号）创建设备文件1、手动创建mknod /dev/led c 250 0 ，其中dev/led 为设备节点 ,c 代表字符设备, 250代表主设备号, 0代表次设备号。设备驱动程序中如何注册一个字符设备？1、将cdev结构嵌入到自己的设备特定结构中void cdev_init(struct cdev *cdev, struct file_operations *fops)2、早期注册函数int register_chrdev(unsigned int major, const char *namem , struct file operations *fopen);Linux设备中字符设备和块设备有什么主要区别？**字符设备：**提供连续的数据流，应用程序可以顺序读取，通常不支持随机存取。**块设备：**应用程序可以随机访问设备数据，程序可自行确定读取数据的位置。驱动中操作物理绝对地址为什么要先ioremap？1、ioremap是将io地址空间映射到虚拟地址空间上去，便于操作。2、因为保护模式下的cpu只认虚拟地址，不认物理地址，所以你要操作外设上的寄存器必须先映射到虚拟内存空间，拿着虚拟地址去跟cpu对接，从而操作寄存器。Linux移植ARM的基本步骤和完成的任务1）首先是准备工作，包括下载源码、建立交叉编译环境等；2）然后是配置和编译内核，必要时还要对源码做一定的修改；3）第三步就是需要制作文件系统（如RAM disk）来挂接根文件系统；4）最后是下载、调试内核并在fs中添加自己的应用程序。ARM-linux启动分几部分，简述流程：ARM-linux启动分为四个部分：引导加载程序（bootloader），Linux内核，文件系统，应用程序。bootloader是系统启动和复位后执行的第一段代码，它主要用来初始化处理器及外设，然后调用Linux内核。Linux内核在完成系统的初始化之后需要挂载某个文件系统作为根文件系统（root filesystem）。根文件系统是Linux系统的核心组成部分，它可以作为Linux系统中文件和数据的存储区域，通常它还包括配置文件运行应用程序所需要的库。应用程序实现该嵌入式产品所要实现的目标。4、操作系统什么是进程？什么是线程？进程是资源分配的基本单位，它是程序执行时的一个实例，在程序运行时创建。线程是程序执行的最小单位，是进程的一个执行流，一个线程由多个线程组成的。进程和线程有什么区别？1、进程是资源分配的基本单位，线程是程序运行的基本单位2、进程有自己的资源空间，线程是共享进程中的数据，所以进程切换开销更大一点3、线程通讯要简单一些，因为共享全局变量等4、线程执行开销小，进程执行开销大。5、多线程中一个线程死掉整个进程也死了，一个进程死掉不会影响其他进程，因为它有独立的地址空间。何时使用多进程，何时使用多线程？对资源的管理和保护要求高，不限制开销和效率时，使用多进程。要求效率高，频繁切换时，资源的保护管理要求不是很高时，使用多线程。进程有几种状态？创建状态就绪状态运行状态阻塞状态终止状态进程间通信方式管道(pipe)管道这种通讯方式有两种限制，一是半双工的通信，数据只能单向流动，二是只能在具有亲缘关系的进程间使用信号量(semophore)信号量是一个计数器，可以用来控制多个进程对共享资源的访问。它常作为一种锁机制，防止某进程正在访问共享资源时，其他进程也访问该资源。因此，主要作为进程间以及同一进程内不同线程之间的同步手段。消息队列(message queue)消息队列是由消息组成的链表，存放在内核中并由消息队列标识符标识。共享内存(shared memory)共享内存就是映射一段能被其他进程所访问的内存，这段共享内存由一个进程创建，但多个进程都可以访问。共享内存是最快的 IPC 方式，它是针对其他进程间通信方式运行效率低而专门设计的。它往往与其他通信机制，如信号量，配合使用，来实现进程间的同步和通信。套接字(socket)套解字也是一种进程间通信机制，与其他通信机制不同的是，它可用于不同机器间的进程通信。线程间的通讯方式（1）通过条件变量进行线程间的通信（2）通过标志位来通知线程间的通信（3）通过std::furture来进行线程间的通信线程间同步方法有哪些？**临界区：**如果有多个线程试图访问共享资源，那么当有一个线程进入后，其他试图访问共享资源的线程将会被挂起，并一直等到进入临界区的线程离开，临界在被释放后，其他线程才可以抢占。互斥量：为协调对一个共享资源的单独访问而设计，只有拥有互斥量的线程，才有权限去访问系统的公共资源，因为互斥量只有一个，所以能够保证资源不会同时被多个线程访问。**信号量：**为控制一个具有有限数量的用户资源而设计。它允许多个线程在同一个时刻去访问同一个资源，但一般需要限制同一时刻访问此资源的最大线程数目事件：用来通知线程有一些事件已发生，从而启动后继任务的开始。什么是僵尸进程，孤儿进程，守护进程？僵尸进程是 一个进程使用fork创建子进程，如果子进程退出，而父进程并没有调用wait或waitpid获取子进程的状态信息，那么子进程的进程描述符仍然保存在系统中。这种进程称之为僵死进程。孤儿进程是因为父进程异常结束了，然后被1号进程init收养。守护进程是创建守护进程时有意把父进程结束，然后被1号进程init收养请你回答一下fork和vfork的区别？fork( )的子进程拷贝父进程的数据段和代码段；vfork( )的子进程与父进程共享数据段fork( )的父子进程的执行次序不确定；vfork( )保证子进程先运行，在调用exec或exit之前与父进程数据是共享的，在它调用exec或exit之后父进程才可能被调度运行。vfork( )保证子进程先运行，在它调用exec或exit之后父进程才可能被调度运行。如果在调用这两个函数之前子进程依赖于父进程的进一步动作，则会导致死锁。当需要改变共享数据段中变量的值，则拷贝父进程。堆和栈什么是代码段，数据段，bss段，堆，栈？代码段：存放程序执行代码的一块区域，通常是只读数据段：已初始化的全局变量和已初始化为非0的静态变量BSS段：未初始化的全局变量和未初始化的静态变量或者初始化为0的静态变量数据段和BSS段本质上都是静态区，存放全局变量和静态变量的堆：堆是用来存放进程中被动态分配的内存段。栈：是用户存放程序临时创建的变量。为什么堆的空间是不连续的？1、堆包含一个链表来维护已用和空闲的内存块。2、分配的空间在逻辑地址（虚拟地址）上是连续的，但在物理地址上是不连续的什么是用户栈和内核栈？内核栈 ：内存中属于操作系统空间的一块区域。作用：1、保存中断现场2、保存调用的参数、返回值、函数局部变量用户栈：用户进程空间的一块区域，用于保存用户空间子程序间调用的参数，返回值以及局部变量。为什么不能共用一个栈：1、系统栈（内核栈）大小有限用户程序调用次数可能很多。2、用户栈空间不能提供相应保护措施线程是否有相同的堆栈？每个线程有自己的堆栈。信号、并发和互斥驱动里面为什么要有并发、互斥的控制？如何实现？讲个例子？并发：多个执行单元同时对共享资源操作，容易导致竞态。互斥：一个执行单元在访问共享资源的时候、其他执行单元都被禁止访问。访问共享资源的代码区被称为临界区，临界区需要某种互斥机制加以保护。自旋锁是什么？信号量是什么？二者有何异同？自旋锁：一个执行单元在操作资源时，另一个执行单元不能操作。自旋锁只能短期持有信号量：资源标量，使用完了就不允许操作了。会有信号告诉需要等多久。适合长期持有的时候用区别：1、长时间持有锁使用信号量，短时间持有使用自旋锁。2、信号量可以睡眠，其他人需要时也会进入睡眠。3、信号量代码可以被抢占。自旋锁和信号量可以睡眠吗？为什么？自旋锁不能睡眠，信号量可以。原因：1、自旋锁自旋锁禁止处理器抢占；而信号量不禁止处理器抢占。自旋锁和信号量可以用于中断中吗？信号量不能用于中断中，因为信号量会引起休眠，中断不能休眠。自旋锁可以用于中断。在获取锁之前一定要先禁止本地中断（也就是本CPU中断，对于多核SOC来说会有多个CPU核），否则可能导致锁死现象的发生产生死锁的原因是什么？多个并发进程因争夺系统资源而产生相互等待的现象。即：一组进程中的每个进程都在等待某个事件发生，而只有这组进程中的其他进程才能触发该事件，这就称这组进程发生了死锁。原因：1、系统资源有限2、进程推进顺序不合理如何避免死锁？1、线程按一定顺序加锁2、获取锁时加上时限，也就是说超过时间则放弃获取。3、死锁检测内存在1G内存的计算机中能否malloc(1.2G)？为什么？malloc能够申请的空间大小与物理内存的大小没有直接关系，仅与程序的虚拟地址空间相关。内存管理的方法1、块式管理​ 分成一大块一大块，只需要几个字节也给一大块。造成浪费、但方便管理。2、页式管理​ 划分地址空间为若干大小区域，被称为页。优点便于管理，缺点页长与逻辑大小没有关系。3、段式管理和段页式管理按照程序的自然分界划分的并且长度可以动态改变的区域，每段可以定义一组相对完整的逻辑信息。段与段在内存中可以不相邻接，也实现了离散分配。段页式管理：用分段方法来分配和管理虚拟存储器。用分页方法来分配和管理内存什么是虚拟内存？它使得应用程序认为它拥有连续可用的内存（一个连续完整的地址空间），允许程序员编写并运行比实际系统拥有的内存大得多的程序好处：1、扩大了地址空间2、地址保护3、公平分配内存：每个进程相当于有了同样大小的额外内存解释下内存碎片，内碎片，外碎片？1、内存碎片：内存碎片是由于多次进行内存分配造成的，空白段太小无法进行下次分配2、内碎片：分配给程序的存储空间没有用完，有一部分是程序不使用（没用完），但其他程序也没法用的空间。3、外碎片：空间太小，小到无法给任何程序分配（不属于任何进程）的存储空间。解释下虚拟地址、逻辑地址、线性地址、物理地址？1、虚拟地址、逻辑地址：由程序产生的由段选择符和段内偏移地址组成的地址这两部分组成的地址并没有直接访问物理内存，而是通过分段地址的变换处理后才会对应到相应的物理内存地址。2、线性地址：指虚拟地址到物理地址变换之间的中间层，是处理器可寻址的内存空间（称为线性地址空间）中的地址。3、物理地址：是指现在CPU外部地址总线上的寻址物理内存的地址信号，是地址变换的最终结果。系统调用是什么，你用过哪些系统调用，和库函数有什么区别？系统调用：系统调用是通向操作系统本身的接口，是面向底层硬件的。通过系统调用，可以使得用户态运行的进程与硬件设备(如CPU、磁盘、打印机等)进行交互，是操作系统留给应用程序的一个接口。库函数：库函数（Library function）是把函数放到库里，供别人使用的一种方式。.方法是把一些常用到的函数编完放到一个文件里，供不同的人进行调用。一般放在.lib文件中。系统调用是为了方便使用操作系统的接口，而库函数则是为了人们编程的方便。区别：1、库函数是语言或应用程序的一部分，系统调用是内核提供的接口。2、库函数在用户地址进行，系统调用在内核地中空间执行3、库函数有缓冲、系统调用无缓冲。4、系统调用依赖平台，库函数不用上下文上下文有哪些？怎么理解？上下文简单说来就是一个环境。用户级上下文: 正文、数据、用户堆栈以及共享存储区；寄存器上下文: 通用寄存器、程序寄存器(IP)、处理器状态寄存器(EFLAGS)、栈指针(ESP)；系统级上下文: 进程控制块task_struct、内存管理信息(mm_struct、vm_area_struct、pgd、pte)、内核栈为什么会有上下文这种概念？系统调用中用户空间会传递很多数据给内核空间，保存上下文以便系统调用结束后回到用户空间继续执行。5、网络编程TCP/ UDPTCP怎么保证可靠性？1、序列号、确认应答、超时重传2、窗口控制与高速重发控制/快速重传（重复确认应答）窗口控制：不需要对每个没收确认的数据重发，只需要确认一个窗口是否都收齐了。简述一下TCP建立连接和断开连接的过程。连接三次握手1、客户端请求，标志位SYN置为1 发送x;2、服务端回复，标志位SYN和ACK都置为1 回复 x+1,和 y3、客户端收到后回复 y+1，服务端检查ack是否为1，是的话就连接成功断开1、客户端发送 x+2 回复y+1 进入FIN_WAIT_1 状态2、服务端回复x+3 服务器进入CLOSE_WAIT状态。客户端收到后进入FIN_WAIT_2状态3、服务端发送完所有数据之后发送y+1 服务器进入LAST_ACK状态4、客户端回复y+2 客户端进入TIME_WAIT状态等待2MSL（报文段最大生存时间）后关闭为什么客户端最后还要等待2MSL？保证客户端发送的最后一个ACK报文能够到达服务器，因为这个ACK报文可能丢失，站在服务器的角度看来，我已经发送了FIN+ACK报文请求断开了，客户端还没有给我回应，应该是我发送的请求断开报文它没有收到，于是服务器又会重新发送一次，而客户端就能在这个2MSL时间段内收到这个重传的报文，接着给出回应报文，并且会重启2MSL计时器。为什么是三次握手？1、为了防止已失效的连接请求报文段突然又送到了，产生错误。2、客户端发送请求报文遗漏，后续才到达时，服务端还是回回复，浪费资源3、客户端发送请求报文后掉线了，服务端还是会回复，浪费资源为什么是四次挥手？二三次能不能合并1、TCP是全双工通信，意味着关闭是双方都需要确认的行为。2、需要时间释放资源，一旦合并需要等很久。3、客户端会以为自己第一次发的报文没有送到，不断尝试发送第一次的报文。TCP/UDP1、TCP面向连接，UDP无连接2、TCP数据保证正确、顺序正确，UDP可能丢包3、TCP可靠稳定，但是慢效率低，UDP快，容易丢包TCP，UDP适用场景？TCP应用场景效率要求相对低，但对准确性要求相对高的场景。文件传输（准确高要求高、但是速度可以相对慢）、接受邮件、远程登录。UDP应用场景效率要求相对高，对准确性要求相对低的场景。QQ聊天、在线视频、网络语音电话、广播通信TCP相比UDP为什么是可靠的？1、确认和重传机制2、数据排序3、流量控制 窗口和计时器的使用4、拥塞控制什么是OSI七层模型和TCP/IP四层模型？每层列举2个协议。物理层: 通过媒介传输比特,确定机械及电气规范,传输单位为bit，主要包括的协议为：IEE802.3CLOCK RJ45数据链路层: 将比特组装成帧和点到点的传递,传输单位为帧,主要包括的协议为MAC VLAN PPP网络层：负责数据包从源到宿的传递和网际互连，传输单位为包,主要包括的协议为IP ARP ICMP传输层：提供端到端的可靠报文传递和错误恢复，传输单位为报文,主要包括的协议为TCP UDP会话层：建立、管理和终止会话，传输单位为SPDU，主要包括的协议为RPC NFS表示层: 对数据进行翻译、加密和压缩,传输单位为PPDU，主要包括的协议为JPEG ASII应用层: 允许访问OSI环境的手段,传输单位为APDU，主要包括的协议为FTP HTTP DNSTCP/IP链路层：MAC VLAN PPP网络层：IP协议、ICMP协议、ARP协议、RARP协议。传输层：UDP协议、TCP协议。应用层：FTP（文件传送协议）、Telnet（远程登录协议）、DNS（域名解析协议）、SMTP（邮件传送协议），POP3协议（邮局协议），HTTP协议。TCP/IP数据链路层的交互过程是怎么样的？网络层等在数据链路层用MAC地址作为通信目标，数据包到达网络层等往数据链路层发送的时候，首先回去ARP缓存表去查找ip对应的MAC地址，如果查到了，就将此ip对应的MAC地址封装到链路层数据包的包头。如果缓存中没有找到，则会发起一个广播寻找目的IP的物理地址。传递到IP层怎么知道报文该给哪个应用程序，它怎么区分UDP报文还是TCP报文？根据端口继续区分需接受的程序；根据ip协议头中标识字段：UDP 17 、TCP 6端口号熟知的端口号：20：FTP 数据传输21/TCP FTP 文件传输协议23/tcp Telnet 不安全的文本传送25/tcp SMTP Simple Mail Transfer Protocol (E-mail)69/udp TFTP Trivial File Transfer Protocol79/tcp finger Finger80/tcp HTTP 超文本传送协议 (WWW)88/tcp Kerberos Authenticating agent110/tcp POP3 Post Office Protocol (E-mail)113/tcp ident old identification server system119/tcp NNTP used for usenet newsgroups220/tcp IMAP3443/tcp HTTPS used for securely transferring web pagesICMP协议属于什么层1.ICMP是基于IP协议工作的，但是它并不是传输层的功能，因此仍然把它归结为网络层协议2.ICMP只能搭配IPv4使用，如果是IPv6的情况下, 需要是用ICMPv6物理地址和IP的转化地址解析协议（ARP）的作用是将IP地址转换成物理地址；反地址解析协议（RARP）则负责将物理地址转换成IP地址。从在浏览器地址栏中输入http://www.baidu.com到看到百度首页，这个过程中间经历了什么？都涉及到哪些网络协议？按照时间顺序：1.客户端浏览器获取用户在地址栏输入的域名。2.客户端浏览器将域名发送给DNS域名系统，请求解析。3.DNS解析域名得到相应的IP，返回给客户端浏览器。4.客户端浏览器根据IP向服务器发起TCP三次握手，建立TCP连接。5.客户端浏览器向服务器发送HTTP请求，请求百度首页。6.服务器通过HTTP响应向客户端浏览器返回百度首页文件。7.释放TCP连接。8.客户端浏览器解析HTML文件，根据文件内容获取CSS、JS等资源文件，将页面渲染展示给用户。HTTP/IP什么是http协议？1、HTTP协议是Hyper Text Transfer Protocol（超文本传输协议）的缩写，是用于从万维网（WWW:World Wide Web）服务器传输超文本到本地浏览器的传送协议。2、HTTP是一个基于TCP/IP通信协议来传递数据ICMP协议属于什么层http协议有什么特点？1、简单快速 客户向服务器请求服务时，只需传送请求方法和路径2、无连接 无连接的含义是限制每次连接只处理一个请求。服务器处理完客户的请求，并收到客户的应答后，即断开连接。3、基于TCP协议4、默认端口80https建立连接过程是什么?客户端连接到Web服务器 一个HTTP客户端，通常是浏览器，与Web服务器的HTTP端口（默认为80）建立一个TCP套接字连接。发送HTTP请求通过TCP套接字，客户端向Web服务器发送一个文本的请求报文服务器接受请求并返回HTTP响应​ Web服务器解析请求，定位请求资源。服务器将资源复本写到TCP套接字，由客户端读取4. 释放连接TCP连接
