__device__ __forceinline__ float block_reduce_sum(float val) {
  constexpr int NUM_WARPS = (NUM_THREADS + WARP_SIZE - 1) / WARP_SIZE;
  int warp = threadIdx.x / WARP_SIZE;
  int lane = threadIdx.x % WARP_SIZE;
  static __shared__ float shared[NUM_WARPS];
  // 1024个数据，有128个线程
  // 一个线程处理8个数据

  // 32个线程作为一个集合进行规约，0+16,1+17，线程2+18
  // 这里的val经过多轮循环之后，线程0的累计值
  // val是32个线程各自局部和之累加
  val = warp_reduce_sum&lt;WARP_SIZE&gt;(val);
  if (lane == 0) shared[warp] = val;
  __syncthreads();
  // 128个线程，32个线程一个规约，还有规约后有4个值
  val = (lane &lt; NUM_WARPS) ? shared[lane] : 0.0f;
  // 再把4个组的值最后规约一遍得到最终的结果

  // 线程0 存放规约值0，线程0-31的局部和
  // 线程1 存放规约值1，线程32-63的局部和
  // 线程2 存放规约值2，线程64-95的局部和
  // 线程3 存放规约值3，线程96-127的局部和
  // 线程4-到线程31 都存放了0值
  val = warp_reduce_sum&lt;NUM_WARPS&gt;(val);
  return val;
}

template&lt;const int kWarpSize = WARP_SIZE&gt;
__device__ __forceinline__ float warp_reduce_sum(float val) {
  #pragma unroll
  for (int mask = kWarpSize &gt;&gt; 1; mask &gt;= 1; mask &gt;&gt;= 1) {
    val += __shfl_xor_sync(0xffffffff, val, mask);
  }
  return val;
}
其中传入的参数val是每个线程的局部和，warp是warp组的编号，lane是某个线程在warp组的偏移，我们先以32个线程作为一个warp，对每32个线程作为一组求规约和。比如我们现在有160个线程，每32个线程作为一个warp，共有五个warp。在第一个warp内的规约中，第一轮循环将线程0和线程16的结果进行加和，将线程1和线程17的结果进行加和，... ，线程8和线程24的局部和结果进行加和。随后在第二轮循环中，跨度会减为原先的一半，所以会将线程0和线程8进行求和，我们知道线程0中在第一轮循环中已经累计了线程0本身和线程16的结果，线程8累计了线程8本身和线程24的结果，所以在第二轮循环中二者相加线程0中便累计了0，16，8，24的值。为了大家更好的理解，我们来看以下的图示：比如我这个图示一个warp，以8个作为一个单位进行规约。以8个线程作为一组进行规约第一轮循环中线程0 = 线程0+线程4，线程0记录0位置的值，线程4记录了位置4的值，线程0记录的就是位置0+位置4的值线程1+线程5 = 1和5线程2+线程6 = 位置2+6线程3+线程7  = 3和7第二轮循环：线程0 = 线程0 + 线程 2 = 0+4+2+6线程1 = 线程1+线程3 = 1+5+3+7位置的值第三轮循环线程0 = 线程0+线程1 = 0+4+2+6+1+3+5+7在上图中，每一层都是规约的不同状态，可以看出第1层规约的时候的步长是4，到第2层开始的规约时的步长等于2，等到第3层的规约时步长等于1，每层的每次规约得在累计不同位置上的局部和。执行逐层规约的就是warp_reduce_sum函数：template&lt;const int kWarpSize = WARP_SIZE&gt;
__device__ __forceinline__ float warp_reduce_sum(float val) {
  #pragma unroll
  for (int mask = kWarpSize &gt;&gt; 1; mask &gt;= 1; mask &gt;&gt;= 1) {
    val += __shfl_xor_sync(0xffffffff, val, mask);
  }
  return val;
}
每次for循环中都和一定跨度后的线程交换数据并累加，到下一个循环中的时候每次的跨度变为上次的1/2，直到最后的跨度变为1，在该跨度下将线程0和线程1中的数据加起来得到最终的全局和结果。我们上面说到，我们以32个线程作为一个单位（warp）去求规约，随后我们还要将5个warp的结果再度进行求和得到最终的结果。我们的解决办法是将warp0的结果放到线程0中，将warp1的结果放到线程1中，... ，最后再将warp4的结果放到线程4中，其余线程编号4-31都置为空，最后再做一次warp内的规约就可以得到最终的结果。向量化存取假设我们现在有35个数据，我们原先的方式是逐个取出求平方和，见以下代码：float sum = 0.0f;
