   sum += in[i] * in[i];
}
在CUDA中，向量化存取是指利用向量数据类型（如CUDA内置的向量类型，例如float2、float3、float4等）来同时加载或存储多个数据元素的一种技术。这种技术可以显著提高内存吞吐量，减少内存访问的次数，从而提升程序的性能。上面代码中每次加载的元素是1个，不能更加充分地利用带宽。假设的35个数据，我们可以以这样的形式进行读取线程0：0，32，64线程0：[0,1,2,3] ，[32,33,34,35] 循环的次数会减少0 - 34 - 78 - 11...28 - 31直到最后一组，因为不能构成4个单位，所以再进行1个1个的处理。static __global__ void row_rmsnorm_f32(float* in, float* wei, float* out, int size, float eps) {
  const int tid = threadIdx.x;

  constexpr int pack_size = 4;
  const int pack_num = size / pack_size;
  const int pack_off = pack_size * pack_num;

  float sum = 0.0f;
  float4* in_pack = reinterpret_cast&lt;float4*&gt;(in);

  for (int i = tid; i &lt; pack_num; i += blockDim.x) {
    float4 in_float4 = *(in_pack + i);
    sum += in_float4.x * in_float4.x;
    sum += in_float4.y * in_float4.y;
    sum += in_float4.z * in_float4.z;
    sum += in_float4.w * in_float4.w;
  }

  for (int i = pack_off + tid; i &lt; size; i += blockDim.x) {
    sum += in[i] * in[i];
  }
