void QuickSort(int head, int tail) {
    if (head &gt;= tail)
	return;
    int l = head, r = tail;
    int idx = l + rand() % (r - l + 1);
    swap(a[l], a[idx]);
    int x = a[l]; 
    while (l &lt; r) {
	while (a[r] &gt;= x &amp;&amp; l &lt; r)
            --r;
	a[l] = a[r];
	while (a[l] &lt;= x &amp;&amp; l &lt; r)
	    ++l;
	a[r] = a[l];
    }
    a[l] = x; 
    QuickSort(head, l - 1);
    QuickSort(l + 1, tail);
}
