void merge(int l1, int r1, int l2, int r2) { // merge 过程相当于合并两个有序数组 
    int b[r2 - l1 + 2] = {0}, cnt = 0; //开一个临时数组存储 
    int p1 = l1, p2 = l2; // p1 和 p2 分别是两段区间的首指针 
    while (p1 &lt;= r1 &amp;&amp; p2 &lt;= r2)
	if (a[p1] &lt;= a[p2]) {
	    b[++cnt] = a[p1];
	    ++p1;
	}
	else {
	    b[++cnt] = a[p2];
	    ++p2;
	}
    while (p1 &lt;= r1) {
	b[++cnt] = a[p1];
	++p1;
    }
    while (p2 &lt;= r2) {
	b[++cnt] = a[p2];
	++p2;
    }
    for (int i=1; i&lt;=cnt; ++i)
	a[l1 + i - 1] = b[i];
}

void MergeSort(int l, int r) {
    if (l &lt; r) {
	int mid = (l + r) &gt;&gt; 1;
	MergeSort(l, mid);
        MergeSort(mid + 1, r);
	merge(l, mid, mid + 1, r);
    }
} 
