        if (target &lt;= 1)    
             return 1;
        int[] temp = new int[target + 1];
        //初始化
        temp[0] = 1;
        temp[1] = 1;
        //遍历相加
        for (int i = 2; i &lt;= target; i++) 
            temp[i] = temp[i - 1] + temp[i - 2];
        return temp[target];
    }
