def preprocess_dataset(
    dataset: Union[&#34;Dataset&#34;, &#34;IterableDataset&#34;],
    tokenizer: &#34;PreTrainedTokenizer&#34;,
    data_args: &#34;DataArguments&#34;,
    training_args: &#34;Seq2SeqTrainingArguments&#34;,
    stage: Literal[&#34;pt&#34;, &#34;sft&#34;, &#34;rm&#34;, &#34;ppo&#34;]
) -&gt; Union[&#34;Dataset&#34;, &#34;IterableDataset&#34;]:
    column_names = list(next(iter(dataset)).keys())
    template = get_template_and_fix_tokenizer(data_args.template, tokenizer)

    def construct_example(examples: Dict[str, List[Any]]) -&gt; Generator[Any, None, None]:
        for i in range(len(examples[&#34;prompt&#34;])):
            query, response = examples[&#34;prompt&#34;][i], examples[&#34;response&#34;][i]
            query = query + &#34;\n&#34; + examples[&#34;query&#34;][i] if &#34;query&#34; in examples and examples[&#34;query&#34;][i] else query
            history = examples[&#34;history&#34;][i] if &#34;history&#34; in examples else None
            system = examples[&#34;system&#34;][i] if &#34;system&#34; in examples else None
            yield query, response, history, system

    def preprocess_pretrain_dataset(examples: Dict[str, List[Any]]) -&gt; Dict[str, Any]:
        # build grouped texts with format `X1 X2 X3 ...` (without &lt;eos&gt;)
        if isinstance(getattr(tokenizer, &#34;tokenizer&#34;, None), tiktoken.Encoding): # for tiktoken tokenizer (Qwen)
            kwargs = dict(allowed_special=&#34;all&#34;)
        else:
            kwargs = dict(add_special_tokens=False)

        tokenized_examples = tokenizer(examples[&#34;prompt&#34;], **kwargs)
        concatenated_examples = {k: list(chain(*tokenized_examples[k])) for k in tokenized_examples.keys()}
        total_length = len(concatenated_examples[list(concatenated_examples.keys())[0]])
        block_size = data_args.max_source_length
        # we drop the small remainder, and if the total_length &lt; block_size, we exclude this batch
        total_length = (total_length // block_size) * block_size
        # split by chunks of max_source_length
        result = {
            k: [t[i: i + block_size] for i in range(0, total_length, block_size)]
            for k, t in concatenated_examples.items()
        }
        return result

    def preprocess_supervised_dataset(examples: Dict[str, List[Any]]) -&gt; Dict[str, Any]:
        # build inputs with format `&lt;bos&gt; X Y &lt;eos&gt;` and labels with format `&lt;ignore&gt; ... &lt;ignore&gt; Y &lt;eos&gt;`
        # for multiturn examples, we only mask the prompt part in each prompt-response pair.
        model_inputs = {&#34;input_ids&#34;: [], &#34;attention_mask&#34;: [], &#34;labels&#34;: []}
        max_length = data_args.max_source_length + data_args.max_target_length

        for query, response, history, system in construct_example(examples):
            input_ids, labels = [], []

            for source_ids, target_ids in template.encode_multiturn(tokenizer, query, response, history, system):
                if len(source_ids) &gt; data_args.max_source_length:
                    source_ids = source_ids[:data_args.max_source_length]
                if len(target_ids) &gt; data_args.max_target_length:
                    target_ids = target_ids[:data_args.max_target_length]

                if len(input_ids) + len(source_ids) + len(target_ids) &gt; max_length:
                    break

                input_ids += source_ids + target_ids
                labels += [IGNORE_INDEX] * len(source_ids) + target_ids

            model_inputs[&#34;input_ids&#34;].append(input_ids)
            model_inputs[&#34;attention_mask&#34;].append([1] * len(input_ids))
            model_inputs[&#34;labels&#34;].append(labels)

        return model_inputs

    def preprocess_unsupervised_dataset(examples: Dict[str, List[Any]]) -&gt; Dict[str, Any]:
        # build inputs with format `&lt;bos&gt; X` and labels with format `Y &lt;eos&gt;`
        model_inputs = {&#34;input_ids&#34;: [], &#34;attention_mask&#34;: [], &#34;labels&#34;: []}

        for query, response, history, system in construct_example(examples):
            source_ids, target_ids = template.encode_oneturn(tokenizer, query, response, history, system)

            if len(source_ids) &gt; data_args.max_source_length:
                source_ids = source_ids[:data_args.max_source_length]
            if len(target_ids) &gt; data_args.max_target_length:
                target_ids = target_ids[:data_args.max_target_length]

            model_inputs[&#34;input_ids&#34;].append(source_ids)
            model_inputs[&#34;attention_mask&#34;].append([1] * len(source_ids))
            model_inputs[&#34;labels&#34;].append(target_ids)

        return model_inputs

    def preprocess_pairwise_dataset(examples):
        # build input pairs with format `&lt;bos&gt; X`, `Y1 &lt;eos&gt;` and `Y2 &lt;eos&gt;`
        model_inputs = {&#34;prompt_ids&#34;: [], &#34;chosen_ids&#34;: [], &#34;rejected_ids&#34;: []}
        for query, response, history, system in construct_example(examples):
            prompt_ids, chosen_ids = template.encode_oneturn(tokenizer, query, response[0], history, system)
            _, rejected_ids = template.encode_oneturn(tokenizer, query, response[1], history, system)

            if len(prompt_ids) &gt; data_args.max_source_length:
                prompt_ids = prompt_ids[:data_args.max_source_length]
            if len(chosen_ids) &gt; data_args.max_target_length:
                chosen_ids = chosen_ids[:data_args.max_target_length]
            if len(rejected_ids) &gt; data_args.max_target_length:
                rejected_ids = rejected_ids[:data_args.max_target_length]

            model_inputs[&#34;prompt_ids&#34;].append(prompt_ids)
            model_inputs[&#34;chosen_ids&#34;].append(chosen_ids)
            model_inputs[&#34;rejected_ids&#34;].append(rejected_ids)
        return model_inputs

    def print_supervised_dataset_example(example):
        print(&#34;input_ids:\n{}&#34;.format(example[&#34;input_ids&#34;]))
        print(&#34;inputs:\n{}&#34;.format(tokenizer.decode(example[&#34;input_ids&#34;], skip_special_tokens=False)))
        print(&#34;label_ids:\n{}&#34;.format(example[&#34;labels&#34;]))
        print(&#34;labels:\n{}&#34;.format(tokenizer.decode([
            token_id if token_id != IGNORE_INDEX else tokenizer.pad_token_id for token_id in example[&#34;labels&#34;]
        ], skip_special_tokens=False)))

    def print_pairwise_dataset_example(example):
        print(&#34;prompt_ids:\n{}&#34;.format(example[&#34;prompt_ids&#34;]))
        print(&#34;prompt:\n{}&#34;.format(tokenizer.decode(example[&#34;prompt_ids&#34;], skip_special_tokens=False)))
        print(&#34;chosen_ids:\n{}&#34;.format(example[&#34;chosen_ids&#34;]))
        print(&#34;chosen:\n{}&#34;.format(tokenizer.decode(example[&#34;chosen_ids&#34;], skip_special_tokens=False)))
        print(&#34;rejected_ids:\n{}&#34;.format(example[&#34;rejected_ids&#34;]))
        print(&#34;rejected:\n{}&#34;.format(tokenizer.decode(example[&#34;rejected_ids&#34;], skip_special_tokens=False)))

    def print_unsupervised_dataset_example(example):
        print(&#34;input_ids:\n{}&#34;.format(example[&#34;input_ids&#34;]))
        print(&#34;inputs:\n{}&#34;.format(tokenizer.decode(example[&#34;input_ids&#34;], skip_special_tokens=False)))

    if stage == &#34;pt&#34;:
        dataset = dataset.filter(lambda example: example[&#34;prompt&#34;])
        preprocess_function = preprocess_pretrain_dataset
        print_function = print_unsupervised_dataset_example
    elif stage == &#34;sft&#34; and not training_args.predict_with_generate:
        dataset = dataset.filter(lambda example: example[&#34;prompt&#34;] and example[&#34;response&#34;])
        preprocess_function = preprocess_supervised_dataset
        print_function = print_supervised_dataset_example
    elif stage == &#34;rm&#34;:
        dataset = dataset.filter(lambda example: example[&#34;prompt&#34;] and len(example[&#34;response&#34;]) &gt; 1)
        preprocess_function = preprocess_pairwise_dataset
        print_function = print_pairwise_dataset_example
    else:
        dataset = dataset.filter(lambda example: example[&#34;prompt&#34;])
        preprocess_function = preprocess_unsupervised_dataset
        print_function = print_unsupervised_dataset_example

    with training_args.main_process_first(desc=&#34;dataset map pre-processing&#34;):
        kwargs = {}
        if not data_args.streaming:
            kwargs = dict(
                num_proc=data_args.preprocessing_num_workers,
                load_from_cache_file=not data_args.overwrite_cache,
                desc=&#34;Running tokenizer on dataset&#34;
            )

        dataset = dataset.map(
            preprocess_function,
            batched=True,            
            remove_columns=column_names,
            **kwargs
        )

        print_function(next(iter(dataset)))
        return dataset1、preprocess_pretrain_dataset处理PreTraining阶段的数据数据组成形式：输入input： &lt;bos&gt; X1 X2 X3标签labels：X1 X2 X3 &lt;/s&gt;典型的Decoder架构的数据训练方式；2、preprocess_supervised_dataset处理SFT阶段的数据数据组成形式：输入input：&lt;bos&gt; prompt response标签labels： -100 ... -100 response &lt;/s&gt;这里面labels的重点在于prompt部分的被-100所填充，主要作用在下面会介绍到。不同模型的loss计算从Baichuan-13b，qwen-7b，和chatglm的源码来看，现在的LLM都采用的是Decoder-Only的架构，所以整体的loss函数都是相同的。举例来说：假设输入一段文本”我是一个中国人“，那么处理完后的序列示意如下所示，最后计算shifit_logits和shift_labels的交叉熵损失。输入文本&lt;bos&gt;我是一个中国人&lt;/s&gt;shift_logits&lt;bos&gt;我是一个中国人shift_labels我是一个中国人&lt;/s&gt;模型整体的代码实现如下：###pass
lm_logits = self.lm_head(hidden_states)
loss = None
if labels is not None:
    labels = labels.to(lm_logits.device)
    shift_logits = lm_logits[..., :-1, :].contiguous()
    shift_labels = labels[..., 1:].contiguous()
    loss_fct = CrossEntropyLoss()
    loss = loss_fct(
        shift_logits.view(-1, shift_logits.size(-1)), shift_labels.view(-1)
    )

### pass好了，乍一看上面这个loss貌似只是预训练PreTraining阶段的loss，SFT阶段的loss难道也是这么算的吗？答案是肯定的。SFT阶段数据的输入输出格式是&lt;prompt,response&gt;的形式，实际训练过程中应该是给定prompt，计算response部分的loss，但是这个是怎么实现的呢？关键的要点来了，还记得在数据预处理阶段labels的加工方式吗？对于prompt部分的labels被-100所填充，导致在计算loss的时候模型只计算response部分的loss，-100的部分被忽略了。而这个机制得益于torch的CrossEntropyLossignore_index参数，ignore_index参数定义为如果labels中包含了指定了需要忽略的类别号（默认是-100），那么在计算loss的时候就不会计算该部分的loss也就对梯度的更新不起作用，详情可以查看这部分的定义。最后，可以看出不管是PreTraining阶段还是SFT阶段，loss函数都是一样的，只是计算的方式存在差异，PreTraining阶段计算的是整段输入文本的loss，而SFT阶段计算的是response部分的loss。附录个人学习Notes-大模型SFT介绍大模型大在哪里？好好给它算一算显存大模型配置生成参数的解释大模型SFT真的能学到新知识吗？从样本的角度看如何提升大模型微调的性能Prompt Engineering综述Dolma: an Open Corpus of Three Trillion Tokens for Language Model Pretraining Researchhelloai：[论文阅读]大型语言模型检索增强生成综述检索噪声对RAG有没有用？LLM内部先验知识与RAG冲突了怎么办？参考链接https://github.com/hiyouga/LLaMA-Efficient-Tuninghttps://huggingface.co/Qwen/Qwen-7B/blob/main/modeling_qwen.pyhttps://huggingface.co/baichuan-inc/Baichuan-13B-Chat/tree/mainhttps://huggingface.co/THUDM/chatglm2-6b

前段时间在清洗 sft 的数据，不得不说这工作是真磨人啊，细节多到让人抓狂。可能，这就是为什么从业者们都懂得 llm 的方法论，却依然没几个团队能造出好数据训出好模型吧。借此机会，举个例子给大家聊聊 sft 数据能有多少繁琐的细节？也算是吐槽和分享自己的日常了。先说一下为什么都 2024 年底了，还需要清洗 sft 数据，这不应该是去年就已经完成的工作吗？因为数据会过时，去年的高质量数据不代表今年还是高质量数据。例如，user：你会选择猫作为宠物还是狗呢？去年的大语言模型：作为大语言模型，我无法养宠物，吧啦吧啦。今年的大语言模型：猫吧啦吧啦，狗吧啦吧啦，虽然我没有实体，但我推荐你吧啦吧啦。显然，在去年，过度的安全是在大家的认可和接受范围之内的，但今年只会让用户觉着无趣，因此这条数据需要清洗，需要结合用户偏好和实效性重新标注再加人工重新 review —— 总之，只要模型还在迭代，我们清洗 sft 数据的工作就不会停滞。题外话说完了，下面我以一个巨简单的 case 作为切入点，来谈谈 sft 的数据细节有多繁琐。这个 case 就是&#34;以 json 格式输出&#34;。json 大家都很熟悉吧，我就不解释了。在我的认知里，json 就是能被 json.loads() 调用成功且不报错的字符串，想让模型做到以 json 格式输出也很简单，让 answer 过两行代码就搞定了。data = json.loads(line)
json_str = json.dumps(data, indent=2, ensure_ascii=False)大家肯定不觉着 json 工作有啥好展开说的，但有没有一种可能，json 格式还有变种：makrdown 格式，需要在字符串前后加 ``json 和 ``` ，一般默认都要带上；indent = 4 呢 还是 indent = 2 呢还是 indent = 0 呢，prompt 说了还好办，prompt 要是没说呢，难道模型随机选一个数字来输出吗？我们需要统一 answer 中所有的 json 默认 indent；有一种格式叫 jsonl，或者说是把 json 结果输出到一行中；有一种需求叫不准进行 markdown 渲染；有两种 prompt 分别叫：“先分析，再输出 json” 和 “除了 json，其他内容一律不准输出”；……emm，目前为止，大家可能还是不觉着 json 格式有多烦人，无非就是两个工作嘛：选一个默认的 json 格式：带不带 markdown，indent 设置成几，是否输出在一行。然后把 sft 中所有涉及到的 json 数据全部清洗成这种格式；补充那些对  json 格式有明确要求的 prompt，让模型不丢失灵活切换 json 格式的能力。那我就继续提问： 如果 prompt 里有 few_shot，但这个 few_shot 它是一个错误的 json，这时候是让模型模仿这个错误的 json 还是让模型严格按照 json 格式输出呢？我随手测了下市面上体量最大的五家公司，好家伙给我五个答案 (do_sample = True）：4o: markdown + 标准 json + indent 2豆包：标准 json + indent 0kimi：markdown + few_shot_json + jsonlqwen：few_shot_json + jsonl文心：markdown + 标准 json + indent 4你问我谁对，我只能说不知道。都是在尝试去 follow 格式，只不过有的模型是在 follow few_shot 的格式，有的模型是在 follow json 的格式。大家都对，全赢！我只是想用这个 case 强调，在训模型的时候，我们可以选用任何一种 json 风格，但是一定要统一。不要让模型随机出 json 风格，那不仅不利于模型训练，也会给用户的批量请求带来困扰。至于用哪种风格，让 PM 去调研一下客户需求即可。大家也不要吐槽我的这个 prompt，觉着我是在没事儿找事儿，从业者应该都知道，这就是用户们最喜欢用的 prompt，你难道指望用户每次请求的时候，先去检验一下自己的示例是不是一个标准化 json 吗？单引号，中文引号，中文逗号，括号不匹配，……，各种错误比比皆是。GPT4okimiqwen 2.5文心 3.5豆包到了这一步，你是不是有点认同我“以 json 格式输出”不是一个简单的工作了。但别着急，我还有一个问题要问：在数值任务上，针对数字，json 格式是使用 float / int 类型呢，还是 str 类型呢？大家肯定都想选前者，我认同，但我要提醒一下，前者会影响模型的准确率，因为数值任务有个要素叫“单位”。GPT4o这里必须质问 ChatGPT 老师，我的单位“百万$” 去哪里了？虽然没有在 prompt 中明确指出要带单位，但这不应该是默认的常识吗？我们不能指望用户写出高质量的 prompt 呀。当然，我并不是要为了拷打 ChatGPT 老师，我是想表达，在 next_token_prediction 的过程中，当模型的 “net_profit”: 的下一个 token 生成了数字 5，而不是双引号 &#34; 的时候，神仙也救不回来这个 response 了。因为一旦没有输出引号，就代表模型选择了输出数值类型，那就必然没办法带单位了。这也就是我说的让模型习惯用 float / int 类型输出数值，可能会影响效果的原因。不过也有补救办法，构造 sft 数据提醒模型每次额外输出一个 unit 字段。{
