#         self.next = None

class Solution:
    def mergeKLists(self, lists: List[ListNode]) -&gt; ListNode:
        lists_len = len(lists)
        if lists_len == 0:
            return 
        return self.merge(lists,0,lists_len-1)

    def merge(self,lists,left,right):
        if left == right:
            return lists[left]
        mid = left+(right-left)//2
        l1 = self.merge(lists,left,mid)
        l2 = self.merge(lists,mid+1,right)
        return self.mergeTwoList(l1,l2)

    def mergeTwoList(self,l1,l2):
        head = ListNode(0)
        h = head
        while l1 and l2:
            if l1.val &gt;= l2.val:
                h.next = l2
                l2 = l2.next
            else:
                h.next = l1
                l1 = l1.next
            h = h.next
        if l1:
            h.next = l1
        if l2:
            h.next = l2 
        return head.next个人本次面试总结很多题目非常强调实践，没有做过大模型的项目且没有针对性准备过，很难回答上。大模型微调是很多公司的考察重点。几种模型的注意力机制、位置编码要熟悉。RLHF的几步多熟悉熟悉美团-大模型算法工程师面经小米-NLP算法工程师面试题好未来-NLP算法工程师面经百度大模型算法工程师面经算法工程师面试常考手撕题搜狐大模型算法工程师字节大模型算法实习生理想汽车大模型算法实习生百度大模型算法实习生面试题腾讯大模型算法实习生面试题阿里大模型算法工程师一面某大厂大模型算法工程师面试题说说百度大模型算法工程师二面经历昆仑天工大模型算法工程师

前言:6月辞职之后就开始了全世界跑(主要是去玩), 然后在 9 月 14 号飞机回国之后就一直在准备面试, 公司投的不多, 就这三家. 最后也是一波三折的拿到了微软的 offer, 回想起来也是看了很多网上的文章, 非常有用, 但是吧大多数你能看到都是 JAVA 题, 而我本人不写 JAVA, 所以这里想写一下这两个月做的准备来帮助以后各位想要进这些公司的人. 当然啦, 并不是说看完文章就可以的了, 各位还是需要自己多多花时间准备, 把基础准备好了, 有把握了再开始申请.首先我申请的岗位都是后台开发, 腾讯的是在广州的, 字节跳动是在深圳的岗位, 然后微软本来是北京的, 那个挂了之后申请了苏州的过了. 这也就是为什么我现在这么闲来写这篇文章. 我个人使用的技术栈是 python + Go, 腾讯用的多是 C等语言, 字节跳动的技术栈跟我的蛮搭的, 微软就不用说了, 自成一套体系. 然后声明一下, 我本身的数据库知识是不咋地, 以前也没怎么写, 也不知道为什么刚好所有的面试都没问到我数据库的东西, 感觉有些碰巧. 出于对这些公司的尊重吧, 我也不会把题目都原题公布, 大部分段落准备讲一下我是怎么准备的, 以及一些个人想法, 其实主要还是我也不太记得题目了.前言 2nd其实在面试国内的这些公司的时候还面试了新加坡的 Shopee, Garena, 以及 Micron. 有幸的都挂了, 非常讨厌新加坡, 原因这里我就不多说什么了. 他们的面试用到的是一个叫 Glider 的工具, 网页上的, 极其不好用, 考察算法的同时还要考察你会不会读 user input. 而它的 python2 和 python3 的 template 都是有 bug 的, 导致我算法写完了但是测试没过.Micron 是内推的, 直接视频面试问了很多关于数据库的问题, 那么正如我之前所说没怎么看数据库, 所以这一块是挂的很理所当然.Shopee 考了一题 Reconstruct tree, given preorder and inorder traversal lists. 嗯, 这题很基础, 可惜当时我没看 tree 的题, 就想了半天, 最后时间上差一点. Garena 考的就不记得了, 反正也不难. 就是test cases 没过, 难搞噢.腾讯面试 - 1面 Video Interview腾讯面试的时候一面是QQ 视频 + desktop share, 面试官看起来有些年纪了. 一上来问了一题网上随便一搜都能搜到的腾讯面试题 (啊既然到处都能搜到我发出来应该没关系吧):已知 100 个人里面有1 个人患病, 而我们的测试方法的正确率是 99%. 问, 如果一个人被测出来患病, 那他确诊患病的概率是多少?我发现我可能真是个&#34;天才&#34;, 看到题目二话不说我就回答了一个 99%. 对吧, 我当时想的是检测方法的准确率为 99%, 那我们测出来任意一个人他患病的几率不就是 99%. 然后面试官提示说不对, 接下来我想到了 Bayes theorem, 但是我当时把公式忘得一干二净, 遂放弃. 这里 po 一下公式: 嗯, 我现在懒得套公式了. 反正最后我是这样想的, 100个人里有1个病人, 然后用99%正确的测试方法去测试我们的期望值是 99 (健康) *  1 % + 1 (患病) * 99% = 1.98 ~= 2也就是说最后我们Expect 测出两个病人, 那么只有一个人确实有病, 也就是说这个病人确诊的概率为 50%.说实话现在想起来, 这一题好像这么做也不太对, 但是我也懒得去找正确的做法了. 有兴趣的自行 google 吧!考完这题之后就是两道算法题. 出于对面试官准备题目也不易的尊重, 我在这里给大家放两题类似的但不是原题的.第一题, 在旋转数组中找 targetSearch in rotated array思路也很简单, 用二分法 (也是原题主要考点), 关键就是如何判断我们要找的数是在 left 还是 right. 这题太简单了我就不多说了.第二题, custom 排序Custom sort string原题比这个简单一点, 而且原题是的确要给一个 array 排序, 根据所需的条件来写一个判断大小的算法. 由于这一例题我没做, 我就不贴答案了. 反正中心思想在于判断大小 (谁前谁后), 然后你是选 bubble sort, 还是 selection sort, 还是什么乱七八糟的 sort 的都可以.问完这两题之后时间已经过去 90 分钟多了, 面试官不知道为什么明明一脸的不满意但是还是要问接下来的问题. 嗯, 主要就是他说我做题太慢了. 我平时做题也慢呀, 慢工出细活呀, 你看我写的代码有 bug 吗! 当然, 我当时是没有这么说的, 该怂还是得怂. 我就嘻嘻哈哈的尴尬的陪笑了一下.接下来的问题就五花八门, 这里给大家提一道必考题:TCP 三次握手四次挥手 + TCP v/s UCP这里我建议大家面试前背一遍, 也不多, 11 个 state, 7 ~ 8 条线, 1~2 小时能背下来. 然后我还背了个这个 (虽然完全没考到, 但是我觉得挺好玩的):接下来面试官由 TCP 衍生到了 HTTP + HTTPSHTTP 与 HTTPS 有什么区别?HTTP, hypertext transfer protocol, is a transmission protocol at application layer. It is based on TCP over port 80, but it can also be based on UDP. HTTPS is a secured transfer protocol based on http; it can only use TCP over port 443 and it uses multiple encryption methods to ensure the security of transferred data.再问 (偷懒啊我, 我自己笔记都写的英文, 就不翻译了.)HTTPS 都用了什么加密方法?HTTPS used both symmetrical and asymmetrical methods for encryption. The server has public key and private key. When a client sends a request to the server, the server first responds with its public key, the client will then authenticate the server from a third party, namely our CA authority; then the client generates a random key, for example, K1, and encrypt his key with the public key from server, then the client sends its encrypted key to the server. Server then resolve this encrypted key with its private key to get K1, and the coming communications will be encrypted with K1.面试官猛的一问, 哎? 你怎么说 HTTP 是基于 TCP 的呢? 它需要建立一个连接吗? 这一问当时我确实是不会, 因为我只记得看的时候是基于 TCP 的呀, 但是我们平时用的时候好像又不是一个长连接啊. 那么这一问的正确答案参考一次完整的 HTTP 请求:1. client establishes a TCP connection with server through port 802. client sends request such as GET /sample/hello.jsp HTTP/1.13. clients send request header, ending with a newline to indicate the end of this header.4. server responds with HTTP/1.1 200 OK5. server responds with respond header6. server sends data, with its type specified in content-type7. server closes the TCP connection, unless there is connection: keep-alive所以说其实 TCP 连接是会建立的, 只是发完数据之后都断开连接了.接下来就问了操作系统的问题了. 这里的问题我都回答的很快, 问题不是很难, 就不给具体答案了. (如果想进腾讯, 这些操作系统的知识应该是必会, 需要很熟练)线程与进程的区别? (Process control block, scheduler, lightweight v/s heavyweight)共享内存是如何实现的? (mmap 以及 shmmap 的实现)你写过操作系统? 你如何实现你的调度算法? (Priority + Round Robin )你的操作系统怎么管理你的内存? (Page allocator)你怎么管理你的信号? (Signal Capture, System calls, and etc,.)然后让我把我的操作系统的代码发过去, 他说虽然你这面试不咋地吧, 但是你应该会有下一轮的. 说实话这样子的评价我还是第一次听, 那你到底啥意思嘛! 这一面面了 2 个半小时, 筋疲力尽. 腾讯面试 - 2 面 Onsite Interview过了几天, 腾讯就直接发短信到手机上邀请我去广州的 office 进行一场现场面试. 腾讯还是有钱, 广州的 office 就在广州塔边上, 这黄金地理位置呀! 然后腾讯包办了那栋楼的最上面三层, 我去的当天还有个展, 还看到一个单人飞行器, 看着很炫, 不知道能不能飞起来.好了废话不多说, 直接讲面试过程吧.首先一上来这个人就问了一些简单的题, 有关我做过的项目的, 这些题我都不记得了, 只记得问了一个 Redis 为什么这么快? 我就说因为它是单线程的基于内存操作的. 遂问为什么单线程快, 我当时是没答出来, 我就说Maybe 因为它不需要切换线程? 没有 overhead. 其实应该是因为单线程保证了 lock-free, 没有上锁的话省了很多检查.然后就拿了一张字让我做题, 第一题问你知道多少种IPC 以及 RPC? pipes, message queues, shared memory, semaphores, and RPC is just one kind of IPC, the only difference is that it uses network第二问如何做TCP拥塞控制?这题很搞啊, 我答的是 Flow rate control, 其实他想问 congestion control. 就答了半天发现他不是问这个, 很迷. 那么 congestion control 是如何做到的呢? 有两种方式, explicit signaling an implicit signaling: explicit uses a window adv to tell the sender to slow down, and implicit lets the sender guess that it needs to slow down. 还有就是 slow start and congestion avoidance: its send rate goes up by 1 unit if not congested, and when there is congestion it is cut down by half each time. 也就是加法增大, 乘法减少.接下来是三题算法题, 不能再简单了, 就很基础的. 第一题应该是原创的, 没啥特别的技术, 用一个 sliding window 吧. 第二题也是类似以给定一个排好序的旋转数组, 找到它的最大最小值之类的. 基本上就是一个二分法, 啪一声拍上去就完事了. 然后第三题我也不记得了, 难度类似于 TwoSum 吧, 一个 dict 解决的事情.好了完事了之后就没了. 他让我把代码从电脑上抄一遍下来之后就走了. 感觉也没啥难度呀, 走了之后 HR 还立马打电话说要约下一次, 但是却再也没有联系.也许这就是有缘无分吧! 腾讯2 面遂凉凉.字节跳动 1 面 - Video Interview字节跳动的话没有邀请我去 onsite, 所有的面试都是以视频的形式进行. 过了两轮 technical interview 之后第三面类似于合适度匹配挂了.字节跳动用的是牛客网, 一面的是个很年轻的小伙子 (我怎么看着比我还年轻)问题千篇一律, 而这次的算法题直接让我写二分法. 5 分钟写完. 从这几次面试来看, 各公司还是很重视二分法的, 大家多做做, 好好熟悉一下，以及它的一些变体.也许因为这个小伙子比我还年轻吧, 懂的可能还没我多, 整个面试对答如流. 很快我就过了. 字节跳动是我见过最快给答复的, 1 小时后 HR 就打电话说要约下一场面试. 约在了第二天晚上 5 点.字节跳动 2 面 - Video Interview这一面的话也是考了算法. 是一题跟链表有关的. 我觉得类似于这样的:Merge-k-sorted-List刚好我在 leetcode 上写了这题. 把我的答案 po 一下./**
 * Definition for singly-linked list.
 * type ListNode struct {
 *     Val int
 *     Next *ListNode
 * }
 */
func mergeKLists(lists []*ListNode) *ListNode {
    head := &amp;ListNode{}
    if len(lists) &lt; 1 {
        // nothing
        return nil
    }
    if len(lists) &lt; 2 {
        // only one list
        return lists[0]
    }
    cur := head
    for {
        min := math.MaxInt64
        var minIdx int
        var hasMin bool
        for k := 0; k &lt; len(lists); k ++ {
            if lists[k] != nil &amp;&amp; lists[k].Val &lt; min {
                hasMin = true
                min, minIdx = lists[k].Val, k
            }
        }
        if !hasMin {
            break
        }
        hasMin = false
        node := &amp;ListNode{min, nil}
        cur.Next = node
        cur = cur.Next
        lists[minIdx] = lists[minIdx].Next
        if lists[minIdx] == nil {
            lists = append(lists[0:minIdx], lists[minIdx+1:]...)
        }
        if len(lists) == 0 {
            break
        }
    }

    return head.Next
}
